package com.bank.erasure;

import org.junit.jupiter.api.Test;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

class TypeErasureTest {

    @Test
    void runtimeClassIsSame() {
        List<String> strings = new ArrayList<>();
        List<Integer> integers = new ArrayList<>();
        assertThat(strings.getClass()).isEqualTo(integers.getClass());
        // Both are ArrayList at runtime — type parameter erased!
    }

    @Test
    void instanceofWithWildcard() {
        Object obj = new ArrayList<String>();
        // obj instanceof List<String> → compile error!
        assertThat(obj instanceof List<?>).isTrue();  // wildcard OK!
        assertThat(obj instanceof ArrayList<?>).isTrue();
    }

    @Test
    void workaround_classToken() throws Exception {
        String str = create(String.class);
        assertThat(str).isNotNull();
        assertThat(str).isInstanceOf(String.class);
    }

    <T> T create(Class<T> clazz) throws Exception {
        return clazz.getDeclaredConstructor().newInstance();
    }

    @Test
    void bridgeMethod_exists() throws Exception {
        // Account implements Comparable<Account>
        // Compiler generates bridge: compareTo(Object) → compareTo(Account)
        var methods = Arrays.stream(ComparableAccount.class.getDeclaredMethods())
            .filter(m -> m.getName().equals("compareTo"))
            .toList();
        // Two compareTo methods: the real one + the bridge!
        assertThat(methods.size()).isGreaterThanOrEqualTo(1);
    }

    static class ComparableAccount implements Comparable<ComparableAccount> {
        @Override
        public int compareTo(ComparableAccount o) { return 0; }
    }
}
